registrations.body:
& {
  position: relative;
}
& .openui-chart-horizontal-scroll-button {
  position: absolute;
  background-color: var(--openui-foreground, oklch(0.994 0 89.876 / 1));
}
& .openui-chart-horizontal-scroll-button--left {
  top: -23px;
  transform: translateY(-50%);
  left: 20px;
}
& .openui-chart-horizontal-scroll-button--right {
  top: -23px;
  transform: translateY(-50%);
  right: 0px;
}
& .openui-chart-horizontal-scroll-button--disabled {
  visibility: hidden;
  cursor: not-allowed;
  transition: visibility 0.1s linear;
}

& {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  align-items: center;
  width: 36px;
  height: calc(100% - 44px);
  flex-shrink: 0;
  padding-left: var(--openui-space-2xs, 4px);
}
& .openui-chart-vertical-scroll-button {
  background-color: var(--openui-foreground, oklch(0.994 0 89.876 / 1));
  pointer-events: auto;
}
& .openui-chart-vertical-scroll-button--disabled {
  visibility: hidden;
  cursor: not-allowed;
  transition: visibility 0.1s linear;
}

display: flex;
align-items: center;
justify-content: center;
min-height: 200px;
& :where(.openui-chart-empty-text) {
  font: var(--openui-text-body-default, 400 16px/1.5 "Inter", sans-serif);
  letter-spacing: var(--openui-text-body-default-letter-spacing, -0.01em);
  font-variation-settings: var(--openui-font-variation-regular, "wght" 440);
  color: var(--openui-text-neutral-secondary, oklch(0.097 0 0 / 0.6));
}

font: var(--openui-text-label-xs, 400 12px/1.25 "Inter", sans-serif);
letter-spacing: var(--openui-text-label-xs-letter-spacing, -0.01em);
font-variation-settings: var(--openui-font-variation-regular, "wght" 440);
color: var(--openui-text-neutral-secondary, oklch(0.097 0 0 / 0.6));
padding-bottom: var(--openui-space-s, 8px);

font: var(--openui-text-label-xs, 400 12px/1.25 "Inter", sans-serif);
letter-spacing: var(--openui-text-label-xs-letter-spacing, -0.01em);
font-variation-settings: var(--openui-font-variation-regular, "wght" 440);
color: var(--openui-text-neutral-secondary, oklch(0.097 0 0 / 0.6));
text-align: center;

& {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--openui-space-s, 8px);
}
& :where(.openui-chart-legend-axis-label-container) {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--openui-space-m, 12px);
  flex-wrap: wrap;
}
& :where(.openui-chart-legend-axis-label) {
  font: var(--openui-text-label-xs, 400 12px/1.25 "Inter", sans-serif);
  letter-spacing: var(--openui-text-label-xs-letter-spacing, -0.01em);
  font-variation-settings: var(--openui-font-variation-regular, "wght" 440);
  color: var(--openui-text-neutral-secondary, oklch(0.097 0 0 / 0.6));
}
& :where(.openui-chart-legend-axis-label-text) {
  color: var(--openui-text-neutral-primary, oklch(0.097 0 0 / 1));
}
& :where(.openui-chart-legend) {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--openui-space-m, 12px);
  flex-wrap: wrap;
}
&:where(.openui-chart-legend--bottom) {
  padding-top: var(--openui-space-m, 12px);
}
& :where(.openui-chart-legend--collapsed) {
  flex-wrap: nowrap;
  overflow: hidden;
}
& :where(.openui-chart-legend--expanded) {
  flex-wrap: wrap;
}
& :where(.openui-chart-legend-item) {
  display: flex;
  align-items: center;
  gap: var(--openui-space-xs, 6px);
}
& svg:where(.openui-chart-legend-item svg) {
  height: 10px;
  width: 10px;
  color: var(--openui-text-neutral-primary, oklch(0.097 0 0 / 1));
}
& :where(.openui-chart-legend-item-indicator) {
  height: 10px;
  width: 10px;
  flex-shrink: 0;
  border-radius: var(--openui-radius-2xs, 2px);
  background-color: var(--color-bg);
}
& :where(.openui-chart-legend-item-label) {
  font: var(--openui-text-label-xs, 400 12px/1.25 "Inter", sans-serif);
  letter-spacing: var(--openui-text-label-xs-letter-spacing, -0.01em);
  font-variation-settings: var(--openui-font-variation-regular, "wght" 440);
  color: var(--openui-text-neutral-primary, oklch(0.097 0 0 / 1));
}
& :where(.openui-chart-legend-toggle-button) {
  font: var(--openui-text-label-xs, 400 12px/1.25 "Inter", sans-serif);
  letter-spacing: var(--openui-text-label-xs-letter-spacing, -0.01em);
  font-variation-settings: var(--openui-font-variation-regular, "wght" 440);
  color: var(--openui-text-neutral-primary, oklch(0.097 0 0 / 1));
  padding-left: var(--openui-space-2xs, 4px);
  padding-right: var(--openui-space-3xs, 2px);
}
& :where(.openui-chart-legend-toggle-button-icon) {
  width: 1em;
  height: 1em;
  color: var(--openui-text-neutral-primary, oklch(0.097 0 0 / 1));
}
& :where(.openui-chart-legend-item-label-container) {
  display: flex;
  align-items: center;
  gap: var(--openui-space-2xs, 4px);
}
& :where(.openui-chart-legend-item-percentage) {
  font: var(--openui-text-label-xs, 400 12px/1.25 "Inter", sans-serif);
  letter-spacing: var(--openui-text-label-xs-letter-spacing, -0.01em);
  font-variation-settings: var(--openui-font-variation-regular, "wght" 440);
  color: var(--openui-text-neutral-secondary, oklch(0.097 0 0 / 0.6));
}

& {
  display: grid;
  align-items: start;
  min-width: 128px;
  max-width: 240px;
  gap: var(--openui-space-xs, 6px);
  padding: var(--openui-space-xs, 6px);
  color: var(--openui-text-neutral-primary, oklch(0.097 0 0 / 1));
  font: var(--openui-text-label-xs, 400 12px/1.25 "Inter", sans-serif);
  letter-spacing: var(--openui-text-label-xs-letter-spacing, -0.01em);
  font-variation-settings: var(--openui-font-variation-regular, "wght" 440);
  border-radius: var(--openui-radius-l, 10px);
  border: 1px solid var(--openui-border-default, oklch(0.097 0 0 / 0.06));
  background-color: var(--openui-foreground, oklch(0.994 0 89.876 / 1));
  box-shadow: var(
    --openui-shadow-s,
    0 1px 3px -2px oklch(0 0 0 / 0.02),
    0 2px 5px -2px oklch(0 0 0 / 0.04)
  );
}
& :where(.openui-chart-tooltip-label) {
  font: var(--openui-text-label-xs, 400 12px/1.25 "Inter", sans-serif);
  letter-spacing: var(--openui-text-label-xs-letter-spacing, -0.01em);
  font-variation-settings: var(--openui-font-variation-regular, "wght" 440);
  color: var(--openui-text-neutral-primary, oklch(0.097 0 0 / 1));
  overflow-wrap: break-word;
  word-break: break-word;
}
& :where(.openui-chart-tooltip-label-heavy) {
  font: var(--openui-text-label-xs-heavy, 560 12px/1.25 "Inter", sans-serif);
  letter-spacing: var(--openui-text-label-xs-heavy-letter-spacing, -0.01em);
  font-variation-settings: var(--openui-font-variation-medium, "wght" 560);
  color: var(--openui-text-neutral-primary, oklch(0.097 0 0 / 1));
  overflow-wrap: break-word;
  word-break: break-word;
}
& :where(.openui-chart-tooltip-content) {
  display: grid;
  align-items: start;
  min-width: 128px;
  gap: var(--openui-space-xs, 6px);
  color: var(--openui-text-neutral-primary, oklch(0.097 0 0 / 1));
  font: var(--openui-text-label-xs, 400 12px/1.25 "Inter", sans-serif);
  letter-spacing: var(--openui-text-label-xs-letter-spacing, -0.01em);
  font-variation-settings: var(--openui-font-variation-regular, "wght" 440);
  background-color: var(--openui-foreground, oklch(0.994 0 89.876 / 1));
}
& :where(.openui-chart-tooltip-content-item) {
  display: flex;
  width: 100%;
  flex-wrap: wrap;
  gap: var(--openui-space-xs, 6px);
  align-items: flex-start;
}
& :where(.openui-chart-tooltip-content-item--dot) {
  align-items: center;
}
& svg:where(.openui-chart-tooltip-content-item svg) {
  height: 10px;
  width: 10px;
  color: var(--openui-text-neutral-primary, oklch(0.097 0 0 / 1));
}
& :where(.openui-chart-tooltip-content-indicator) {
  flex-shrink: 0;
  border-radius: var(--openui-radius-2xs, 2px);
}
& :where(.openui-chart-tooltip-content-indicator--dot) {
  height: 10px;
  width: 10px;
  background-color: var(--color-bg);
  border-color: var(--color-border);
}
& :where(.openui-chart-tooltip-content-indicator--line) {
  width: 4px;
  background-color: var(--color-bg);
  border-color: var(--color-border);
}
& :where(.openui-chart-tooltip-content-indicator--dashed) {
  width: 0;
  border: 1.5px dashed var(--color-border);
  background-color: transparent;
}
& :where(.openui-chart-tooltip-content-indicator--two-items) {
  margin-top: 2px;
}
& :where(.openui-chart-tooltip-content-value-wrapper) {
  display: flex;
  flex: 1;
  gap: var(--openui-space-s, 8px);
  justify-content: space-between;
  line-height: 1;
}
& :where(.openui-chart-tooltip-content-value-wrapper--nested) {
  align-items: flex-end;
}
& :where(.openui-chart-tooltip-content-value-wrapper--standard) {
  align-items: center;
}
& :where(.openui-chart-tooltip-content-value-wrapper--vertical) {
  flex-direction: column;
  align-items: flex-start;
  justify-content: flex-start;
  gap: var(--openui-space-2xs, 4px);
}
& :where(.openui-chart-tooltip-content-label) {
  display: grid;
  gap: var(--openui-space-xs, 6px);
  color: var(--openui-text-neutral-secondary, oklch(0.097 0 0 / 0.6));
  font: var(--openui-text-label-xs, 400 12px/1.25 "Inter", sans-serif);
  letter-spacing: var(--openui-text-label-xs-letter-spacing, -0.01em);
  font-variation-settings: var(--openui-font-variation-regular, "wght" 440);
}
& span:where(.openui-chart-tooltip-content-label span) {
  display: block;
  overflow-wrap: break-word;
  word-break: break-word;
}
& :where(.openui-chart-tooltip-content-value) {
  font-variant-numeric: tabular-nums;
  color: var(--openui-text-neutral-primary, oklch(0.097 0 0 / 1));
  font: var(--openui-text-label-xs, 400 12px/1.25 "Inter", sans-serif);
  letter-spacing: var(--openui-text-label-xs-letter-spacing, -0.01em);
  font-variation-settings: var(--openui-font-variation-regular, "wght" 440);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
& :where(.openui-chart-tooltip-content-item-separator) {
  width: 100%;
  height: 1px;
  background-color: var(--openui-border-default, oklch(0.097 0 0 / 0.06));
  margin: 0;
}
&
  .openui-chart-tooltip-content-item:last-child
  :where(.openui-chart-tooltip-content-item-separator) {
  display: none;
}
& :where(.openui-chart-tooltip-content-view-more) {
  font: var(--openui-text-label-xs, 400 12px/1.25 "Inter", sans-serif);
  letter-spacing: var(--openui-text-label-xs-letter-spacing, -0.01em);
  font-variation-settings: var(--openui-font-variation-regular, "wght" 440);
  color: var(--openui-text-neutral-primary, oklch(0.097 0 0 / 1));
  text-align: left;
  overflow-wrap: break-word;
  word-break: break-word;
}

& {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  height: 100%;
}
& :where(.openui-stacked-legend-header) {
  width: 100%;
  box-sizing: border-box;
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 0 var(--openui-space-xs, 6px) var(--openui-space-xs, 6px) var(--openui-space-l, 18px);
  color: var(--openui-text-neutral-secondary, oklch(0.097 0 0 / 0.6));
}
& :where(.openui-stacked-legend-header-buttons) {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: var(--openui-space-xs, 6px);
}
& :where(.openui-stacked-legend-header-title) {
  font: var(--openui-text-label-sm, 400 14px/1.25 "Inter", sans-serif);
  letter-spacing: var(--openui-text-label-sm-letter-spacing, -0.01em);
  font-variation-settings: var(--openui-font-variation-regular, "wght" 440);
  color: var(--openui-text-neutral-secondary, oklch(0.097 0 0 / 0.6));
}
& :where(.openui-stacked-legend-scroll-button) {
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}
& :where(.openui-stacked-legend) {
  width: 100%;
  display: flex;
  flex-direction: column;
  justify-content: safe center;
  min-width: 200px;
  overflow-y: scroll;
  height: 100%;
  scrollbar-width: none;
  -ms-overflow-style: none;
  scroll-behavior: smooth;
}
& :where(.openui-stacked-legend__item) {
  width: 100%;
  box-sizing: border-box;
  display: flex;
  flex-direction: row;
  justify-content: space-between;
  align-items: center;
  gap: 10px;
  padding: 4px 8px;
  border-radius: var(--openui-radius-m, 8px);
  transition: all 0.2s ease-in-out;
  height: 32px;
  flex-shrink: 0;
}
& :hover:where(.openui-stacked-legend__item) {
  background-color: var(--openui-sunk, oklch(0.097 0 0 / 0.04));
}
& :where(.openui-stacked-legend__item--active) {
  background-color: var(--openui-sunk, oklch(0.097 0 0 / 0.04));
}
& :where(.openui-stacked-legend__item-label) {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 8px;
  min-width: 0;
  flex: 1;
}
& :where(.openui-stacked-legend__item-color-container) {
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: center;
  gap: 10px;
  height: 100%;
  width: 32px;
  flex-shrink: 0;
}
& :where(.openui-stacked-legend__item-color) {
  width: 10px;
  height: 10px;
  border-radius: 2px;
  transition: all 0.2s ease-in-out;
}
& .openui-stacked-legend__item:hover :where(.openui-stacked-legend__item-color) {
  transform: scale(1.2);
}
& .openui-stacked-legend__item--active :where(.openui-stacked-legend__item-color) {
  transform: scale(1.3);
}
& :where(.openui-stacked-legend__item-label-text) {
  font: var(--openui-text-label-sm, 400 14px/1.25 "Inter", sans-serif);
  letter-spacing: var(--openui-text-label-sm-letter-spacing, -0.01em);
  font-variation-settings: var(--openui-font-variation-regular, "wght" 440);
  color: var(--openui-text-neutral-primary, oklch(0.097 0 0 / 1));
  transition: color 0.2s ease-in-out;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  min-width: 0;
}
& :where(.openui-stacked-legend__item-value) {
  font: var(--openui-text-label-sm, 400 14px/1.25 "Inter", sans-serif);
  letter-spacing: var(--openui-text-label-sm-letter-spacing, -0.01em);
  font-variation-settings: var(--openui-font-variation-regular, "wght" 440);
  color: var(--openui-text-neutral-primary, oklch(0.097 0 0 / 1));
  transition: all 0.2s ease-in-out;
  flex-shrink: 0;
}
& :where(.openui-stacked-legend-show-more-button) {
  width: 100%;
  justify-content: center;
  margin-top: var(--openui-space-2xs, 4px);
}
& :where(.openui-stacked-legend-separator) {
  margin: var(--openui-space-2xs, 4px) 0;
}

& {
  display: flex;
  position: relative;
  gap: 20px;
  align-items: center;
}
&:where(.openui-chart-with-stacked-legend--column) {
  flex-direction: column;
}
&:where(.openui-chart-with-stacked-legend--row) {
  flex-direction: row;
  min-height: 296px;
}
& :where(.openui-chart-with-stacked-legend__chart) {
  width: 100%;
  min-width: 0;
}
& :where(.openui-chart-with-stacked-legend__legend) {
  display: flex;
  justify-content: center;
  width: 100%;
}
&.openui-chart-with-stacked-legend--column :where(.openui-chart-with-stacked-legend__legend) {
  align-items: flex-start;
}
&.openui-chart-with-stacked-legend--row :where(.openui-chart-with-stacked-legend__chart) {
  flex: 1;
}
&.openui-chart-with-stacked-legend--row :where(.openui-chart-with-stacked-legend__legend) {
  flex: 1;
  min-width: 0;
  height: 296px;
  align-items: center;
}
&.openui-chart-with-stacked-legend--row
  .openui-chart-with-stacked-legend__legend
  :where(.openui-stacked-legend-container) {
  justify-content: center;
}
&.openui-chart-with-stacked-legend--row
  .openui-chart-with-stacked-legend__legend
  :where(.openui-stacked-legend) {
  height: auto;
  max-height: 100%;
}

& {
  position: relative;
  aspect-ratio: 1/1;
  min-width: 100px;
  min-height: 100px;
}
& > svg {
  display: block;
}
&:where(.openui-mini-chart--clickable) {
  cursor: pointer;
}
& :where(.openui-mini-line-chart-point) {
  fill: var(--openui-background, oklch(0.97 0 89.876 / 1));
}
@media (prefers-reduced-motion: no-preference) {
  & :where(.openui-mini-chart-mark--animated) {
    opacity: 0;
    animation: ${fadeAppearAnimation} 0.6s ease-out forwards;
  }
}
